布局结构
css/* 全屏渐变背景 */
background: linear-gradient(135度, #82CCF6 0%, #BBE1FA 25%, #ADDB6B 75%, #C1E6A8 100%);
min-height: 100vh;
display: flex;
flex-direction: column;
align-items: center;

/* 容器居中布局 */
max-width: 800px;
width: 100%;
position: relative;
z-index: 2;
毛玻璃效果
css/* 主要毛玻璃容器 */
background: rgba(255, 255, 255, 0.25);
backdrop-filter: blur(30px);
border-radius: 20px;
border: 1px solid rgba(255, 255, 255, 0.3);
box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);

/* 问题卡片毛玻璃 */
background: rgba(255, 255, 255, 0.2);
backdrop-filter: blur(20px);
border: 1px solid rgba(255, 255, 255, 0.3);

/* 控制按钮毛玻璃 */
background: rgba(255, 255, 255, 0.3);
backdrop-filter: blur(10px);

唱片旋转动画
css/* 唱片主体设计 */
width: 250px;
height: 250px;
background: radial-gradient(circle, #1a1a1a 30%, #333 40%, #1a1a1a 70%);
border-radius: 50%;
animation: spin 8s linear infinite;
box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);

/* 旋转动画 */
@keyframes spin {
from { transform: rotate(0deg); }
to { transform: rotate(360deg); }
}

/* 唱片中心孔设计 */
::before {
width: 60px;
height: 60px;
background: #1a1a1a;
border-radius: 50%;
top: 50%;
left: 50%;
transform: translate(-50%, -50%);
}

/* 中心点 */
::after {
width: 12px;
height: 12px;
background: #666;
border-radius: 50%;
transform: translate(-50%, -50%);
}
悬停交互效果提示词
css/* 卡片悬停效果 */
transition: all 0.3s ease;
cursor: pointer;

:hover {
transform: translateY(-5px);
background: rgba(255, 255, 255, 0.3);
box-shadow: 0 15px 35px rgba(0, 0, 0, 0.15);
}

/* 按钮悬停效果 */
:hover {
background: rgba(255, 255, 255, 0.5);
transform: scale(1.1);
}
浮动音符动画
css/* 音符基础样式 */
position: fixed;
font-size: 2rem;
color: rgba(255, 255, 255, 0.6);
animation: float 6s ease-in-out infinite;
pointer-events: none;
z-index: 3;

/* 浮动动画 */
@keyframes float {
0%, 100% { 
transform: translateY(0px) rotate(0deg); 
opacity: 0.6; 
}
50% { 
transform: translateY(-20px) rotate(10deg); 
opacity: 0.8; 
}
}
网格布局
css/* 问题容器网格布局 */
display: grid;
grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
gap: 20px;
width: 100%;

/* 响应式断点 */
@media (max-width: 768px) {
grid-template-columns: 1fr;
font-size: 2rem;
width: 200px;
height: 200px;
}
纹理效果提示词
css/* 噪点纹理覆盖层 */
::before {
content: '';
position: fixed;
width: 100%;
height: 100%;
background: url('data:image/svg+xml,<svg><feTurbulence baseFrequency="0.9"/></svg>');
opacity: 0.03;
pointer-events: none;
}

